    private static long ToLong(object value)
    {
        if (value == null) return 0;
        if (value is int i) return i;
        if (value is long l) return l;
        if (value is short s) return s;
        if (value is byte b) return b;
        if (value is sbyte sb) return sb;
        if (value is uint ui) return ui;
        if (value is ulong ul) return (long)ul;
        if (value is ushort us) return us;
        if (value is char c) return c;
        if (value is bool bl) return bl ? 1 : 0;
        if (value is float f) return (long)f;
        if (value is double d) return (long)d;
        if (value is decimal dm) return (long)dm;
        if (value is string str) return str.Length;
        return value.GetHashCode();
    }
